// Package gen generates project files from platformgo.yaml.
//
// It produces the module wiring, their settings and the environment example. This is
// what removes manual edits when modules are added or removed: only the domain part
// stays in project code.
package gen

import (
	"bytes"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"text/template"

	"github.com/aidarbn/platform-go/internal/registry"
	"github.com/aidarbn/platform-go/internal/spec"
)

// Paths of generated files, relative to the project root.
const (
	ConfigPath  = "cmd/app/config.gen.go"
	ModulesPath = "cmd/app/modules.gen.go"
	EnvPath     = ".env.example"
)

const header = "// Code generated by platformgo from " + spec.FileName + ". Do not edit.\n"

var configTmpl = template.Must(template.New("config").Parse(header + `
package main

import (
{{- range .Imports}}
	"{{.}}"
{{- end}}
)

// Config holds settings of the platform modules of {{.Service}}.
type Config struct {
{{- range .Modules}}
	{{.Field}} {{.ConfigType}}
{{- end}}
}

// LoadConfig reads module settings from environment variables and returns every
// problem at once instead of one per restart.
func LoadConfig() (*Config, error) {
	l := confx.New("")
	cfg := &Config{
{{- range .Modules}}
		{{.Field}}: {{.LoadCall}},
{{- end}}
	}
	if err := l.Err(); err != nil {
		return nil, err
	}
	return cfg, nil
}
`))

var modulesTmpl = template.Must(template.New("modules").Parse(header + `
package main

import (
{{- range .Imports}}
	"{{.}}"
{{- end}}
)

// platformModules returns the project modules in dependency order.
func platformModules(cfg *Config) []platform.Module {
	return []platform.Module{
{{- range .Modules}}
		{{.NewCall}},
{{- end}}
	}
}
`))

type templateData struct {
	Service string
	Imports []string
	Modules []registry.Module
}

// Wiring returns the generated files: path relative to the project root to content.
func Wiring(f *spec.File) (map[string][]byte, error) {
	modules := f.EnabledModules()

	config, err := render(configTmpl, templateData{
		Service: f.Service(),
		Imports: imports("github.com/aidarbn/platform-go/kit/confx", modules),
		Modules: modules,
	})
	if err != nil {
		return nil, fmt.Errorf("%s: %w", ConfigPath, err)
	}

	mods, err := render(modulesTmpl, templateData{
		Service: f.Service(),
		Imports: imports("github.com/aidarbn/platform-go/kit/platform", modules),
		Modules: modules,
	})
	if err != nil {
		return nil, fmt.Errorf("%s: %w", ModulesPath, err)
	}

	return map[string][]byte{
		ConfigPath:  config,
		ModulesPath: mods,
		EnvPath:     env(f, modules),
	}, nil
}

func imports(base string, modules []registry.Module) []string {
	out := []string{base}
	for _, m := range modules {
		if !slices.Contains(out, m.Import) {
			out = append(out, m.Import)
		}
	}
	slices.Sort(out)
	return out
}

func render(t *template.Template, data templateData) ([]byte, error) {
	var buf bytes.Buffer
	if err := t.Execute(&buf, data); err != nil {
		return nil, err
	}
	// Format here: generated code must pass gofmt in the project CI.
	out, err := format.Source(buf.Bytes())
	if err != nil {
		return nil, fmt.Errorf("format: %w", err)
	}
	return out, nil
}

func env(f *spec.File, modules []registry.Module) []byte {
	var b strings.Builder
	b.WriteString("# Generated by platformgo from " + spec.FileName + ". Do not edit.\n")
	b.WriteString("# Service: " + f.Service() + "\n")

	for _, m := range modules {
		if len(m.Env) == 0 {
			continue
		}
		b.WriteString("\n# module " + m.Name + "\n")
		for _, v := range m.Env {
			if v.Comment != "" {
				b.WriteString("# " + v.Comment)
				if v.Required {
					b.WriteString(" (required)")
				}
				b.WriteString("\n")
			}
			b.WriteString(v.Key + "=" + v.Example + "\n")
		}
	}
	return []byte(b.String())
}

// Changed returns the paths whose content in the project differs from the generated
// one. An empty list means generation is up to date.
func Changed(dir string, files map[string][]byte) ([]string, error) {
	var changed []string
	for path, want := range files {
		got, err := os.ReadFile(filepath.Join(dir, path))
		if err != nil {
			if os.IsNotExist(err) {
				changed = append(changed, path)
				continue
			}
			return nil, fmt.Errorf("%s: %w", path, err)
		}
		if !bytes.Equal(got, want) {
			changed = append(changed, path)
		}
	}
	slices.Sort(changed)
	return changed, nil
}

// Apply writes the generated files into the project.
func Apply(dir string, files map[string][]byte) ([]string, error) {
	paths := make([]string, 0, len(files))
	for path := range files {
		paths = append(paths, path)
	}
	slices.Sort(paths)

	for _, path := range paths {
		full := filepath.Join(dir, path)
		if err := os.MkdirAll(filepath.Dir(full), 0o755); err != nil {
			return nil, fmt.Errorf("%s: %w", path, err)
		}
		if err := os.WriteFile(full, files[path], 0o644); err != nil {
			return nil, fmt.Errorf("%s: %w", path, err)
		}
	}
	return paths, nil
}
